/* dc_overlay.h - overlay selection for --target dc.
 *
 * Each overlay is compiled separately (psxrecomp-game --overlay --target dc)
 * and exposes one dispatcher. A registry generated by the game's build lists
 * them with a few sample code words; at a dispatch miss in the main program
 * the runtime runs the overlay whose range holds the address and whose
 * samples match guest RAM, i.e. the image the game actually loaded there.
 */
#pragma once
#include "dc_runtime.h"

#define DC_OVERLAY_SAMPLES 16
typedef struct {
    const char* id;
    uint32_t load, size;
    int nsamples;
    struct { uint32_t addr, word; } samples[DC_OVERLAY_SAMPLES];
    int (*dispatch)(CPUState* cpu, uint32_t addr);
    /* Loadable overlays (dispatch == NULL): compiled code kept in a file and
     * loaded on demand into code slot `slot` (see DcOvSlot). */
    const char* file;
    int slot;
} DcOverlay;

/* A region of host memory that holds one loadable overlay's code at a time.
 * Overlays that the game loads at the same PS1 address share a slot, since
 * they can never be resident together. A loaded file starts with
 * DcOvHeader; the bytes after the file up to header.end are zeroed (bss). */
typedef struct { uint8_t* base; uint32_t size; } DcOvSlot;
#define DC_OV_MAGIC 0x564F4758u   /* "XGOV" */
typedef struct { uint32_t magic, dispatch, end, reserved; } DcOvHeader;
extern const DcOvSlot g_dc_ov_slots[];
extern const int g_dc_ov_slot_count;

/* Provided by the game's generated registry (optional, referenced weakly). */
extern const DcOverlay g_dc_overlays[];
extern const int g_dc_overlay_count;

/* 1 if an overlay ran code at addr. */
int dc_overlay_dispatch(CPUState* cpu, uint32_t addr);
/* Log which overlays cover addr and how many of their samples are resident. */
void dc_overlay_explain(uint32_t addr);

/* Skip a guest function of one overlay: calls to addr while overlay id is
 * resident return at once to $ra with v0 = 0. Used to bypass parts that are
 * not ported yet (FMV). Up to 8 entries. */
void dc_overlay_skip(const char* id, uint32_t addr);
/* Same, but run fn first (it may call guest code with dc_call_guest), so the
 * skip can leave the game state the skipped function would have. */
typedef void (*DcSkipFn)(CPUState* cpu);
void dc_overlay_skip_fn(const char* id, uint32_t addr, DcSkipFn fn);
/* Parse "id@addr[,id@addr...]" (addr in hex), e.g. from an environment variable. */
void dc_overlay_skip_parse(const char* spec);
